/* eslint-disable @typescript-eslint/ban-types */
import { Hooks, TableInstance } from 'react-table';

/** Options on the useTable config object added by the useStickyHeader plugin hook. */
export interface UseStickyHeaderOptions {
  /** Disables the sticky header on the whole table. */
  disableStickyHeader?: boolean;
}

/** Defines props added to the table when useStickyHeader plugin hook is used. */
export interface UseStickyHeaderTableProps {
  /**
   * Data attribute that will be applied to the table when
   * the sticky header is enabled.
   */
  'data-stickyheader'?: boolean;
}

/** Uses the table instance to manipulate and extend the table behavior */
function useInstance(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  instance: TableInstance<any>,
) {
  const { disableStickyHeader, getHooks } = instance;
  if (!disableStickyHeader) {
    getHooks().getTableProps.push((props) => {
      const additionalTableProps: UseStickyHeaderTableProps = {
        'data-stickyheader': true,
      };
      return [props, additionalTableProps];
    });
  }
}

/**
 * Table hook that enables sticky headers.
 * Very simplistic at the moment:
 * FIXME: Does not apply custom styles when table header is stuck
 * FIXME: Does not control overflows correctly.
 */
export function useStickyHeader<
  D extends Record<string, unknown> = Record<string, unknown>,
>(hooks: Hooks<D>): void {
  hooks.useInstance.push(useInstance);
}

useStickyHeader.pluginName = 'useStickyHeader';
